using WypozyczalniaSportowa.Domain.Pricing;
namespace WypozyczalniaSportowa.Domain; public sealed class Kayak : SportEquipment { private int _seats; public Kayak(string n, decimal r, int seats) : base(n, r) => Seats = seats; internal Kayak(int id, string n, decimal r, bool a, bool s, int seats) : base(id, n, r, a, s) => Seats = seats; public int Seats { get => _seats; private set => _seats = value is < 1 or > 4 ? throw new Exceptions.DomainValidationException("Kajak: od 1 do 4 miejsc.") : value; } public override string Kind => "Kajak"; public override int Detail => Seats; public override decimal CalculateRentalPrice(RentalPeriod p, IPricingStrategy s) => s.Calculate(DailyRate, p) * Seats; public override Equipment CloneEntity(bool deep) => new Kayak(Id, Name, DailyRate, IsAvailable, NeedsService, Seats); public override string ToString() => $"{base.ToString()}, miejsca: {Seats}"; }
